	 "items.potions.potion.bistre": "poción bistre",
	 "items.potions.potion.charcoal": "poción carbón",
	 "items.potions.potion.crimson": "poción escarlata",
	 "items.potions.potion.discover_hint": "Puedes encontrar este ítem aleatoriamente en la mazmorra, o crearlo por medio de alquimia.",
	 "items.potions.potion.golden": "poción dorada",
	 "items.potions.potion.harmful": "¡Poción perjudicial!",
	 "items.potions.potion.indigo": "poción índigo",
