	 "windows.wndresurrect.prompt": "Selecione um item",
	 "windows.wndresurrect.title": "Ressurreição",
	 "windows.wndresurrect.warn_body": "Você não selecionou dois itens. Tem certeza de que deseja ressuscitar sem dois itens?",
	 "windows.wndresurrect.warn_no": "Não, deixe-me reconsiderar",
	 "windows.wndresurrect.warn_title": "Itens perdidos",
	 "windows.wndresurrect.warn_yes": "Sim, tenho certeza",
