	 "badges$badge.boss_challenge_1.desc": "Kalahkan bos selokan tanpa membiarkannya menggunakan serangan muatannya atau menyembuhkan dalam air",
	 "badges$badge.boss_challenge_1.title": "Kemenangan Tanpa Noda",
	 "badges$badge.boss_challenge_2.desc": "Kalahkan bos penjara tanpa terkena jebakan atau bahaya apa pun",
	 "badges$badge.boss_challenge_2.title": "Dapat!",
	 "badges$badge.boss_challenge_3.desc": "Kalahkan bos gua tanpa diserang atau terkena damage saat 'serangan super'",
	 "badges$badge.boss_challenge_3.title": "Kalah Manuver",
	 "badges$badge.boss_challenge_4.desc": "Kalahkan bos kota tanpa pernah langsung menyerangnya dengan senjata, cincin, tongkat, atau damage dari mantra",
	 "badges$badge.boss_challenge_4.title": "Tidak Ada Senjata di Kehadirannya",
	 "badges$badge.boss_challenge_5.desc": "Kalahkan bos terakhir dengan semua pemuncul iblis hidup dan tantangan bos yang lebih jahat diaktifkan",
	 "badges$badge.boss_challenge_5.title": "Pembunuh Kiamat",
	 "badges$badge.boss_slain_1.desc": "Kalahkan bos di ujung selokan",
	 "badges$badge.boss_slain_1.title": "Pembersih Slime",
	 "badges$badge.boss_slain_1_all_classes.desc": "Kalahkan bos pertama dengan pahlawan dalam setiap kelas",
	 "badges$badge.boss_slain_1_all_classes.title": "Orang yang Banyak Tahunya",
	 "badges$badge.boss_slain_2.desc": "Kalahkan bos di ujung penjara",
	 "badges$badge.boss_slain_2.title": "Sipir Penjara",
	 "badges$badge.boss_slain_3.desc": "Kalahkan bos di ujung gua",
	 "badges$badge.boss_slain_3.title": "Pembongkar Logam",
	 "badges$badge.boss_slain_3_all_subclasses.desc": "Kalahkan bos ketiga dengan semua subkelas pahlawan",
	 "badges$badge.boss_slain_3_all_subclasses.title": "Orang yang Serba Tahu",
	 "badges$badge.boss_slain_4.desc": "Kalahkan bos di ujung kota",
	 "badges$badge.boss_slain_4.title": "Penakluk Raja",
	 "badges$badge.boss_slain_remains.desc": "Kalahkan bos sambil memegang item tanda tangan pahlawan yang mati pada bos tersebut",
	 "badges$badge.boss_slain_remains.title": "Rasakan Pembalasannya!",
	 "badges$badge.catalog_one_equipment.desc": "Isi satu entri katalog untuk setiap jenis item perlengkapan di jurnal Anda",
	 "badges$badge.catalog_one_equipment.title": "Terpakai",
	 "badges$badge.catalog_potions_scrolls.desc": "Identifikasi semua ramuan dan gulungan biasa dalam satu permainan",
