	 "items.potions.exotic.exoticpotion.azure": "ramuan biru eksotik",
	 "items.potions.exotic.exoticpotion.bistre": "ramuan coklat eksotik",
	 "items.potions.exotic.exoticpotion.charcoal": "ramuan hitam eksotik",
