	 "journal.notes$landmark.ghost": "bánatos kísértet",
	 "journal.notes$landmark.imp": "nagyravágyó kobold",
	 "journal.notes$landmark.rat_king": "patkánykirály",
	 "journal.notes$landmark.sacrificial_fire": "áldozati tűz",
